import React, { useState } from 'react';
import {
  Box, Typography, TextField, Button, Snackbar, Alert
} from '@mui/material';
import { useAuth } from './AuthContext';

const ProfileTab = () => {
  const { user, updateUser } = useAuth();
  const [formData, setFormData] = useState({
    username: user.username,
    password: '',
    newPassword: ''
  });
  const [error, setError] = useState('');
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSnackbar = (message, severity = 'success') => {
    setSnackbar({ open: true, message, severity });
  };

  const closeSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  const handleUpdate = async () => {
    const { username, password, newPassword } = formData;

    if (!password) {
      setError('Current password is required');
      return;
    }

    // Step 1: Verify password
    try {
      const loginResponse = await fetch('http://localhost:8080/worker/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: user.username, password })
      });

      if (!loginResponse.ok) {
        setError('Incorrect password');
        return;
      }

      // Step 2: Send update request
      const updateResponse = await fetch('http://localhost:8080/worker/update', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workerID: user.workerID,
          username,
          password: newPassword, // if empty, backend will ignore
          firstName: user.firstName,
          lastName: user.lastName,
          isAdmin: user.isAdmin
        })
      });

      if (!updateResponse.ok) {
        throw new Error('Failed to update profile');
      }

      handleSnackbar('Profile updated successfully');
      updateUser({ ...user, username }); // optional: update local user context
      setFormData({ ...formData, password: '', newPassword: '' });
      setError('');

    } catch (err) {
      console.error(err);
      handleSnackbar('Error updating profile', 'error');
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h5" gutterBottom>Update Profile</Typography>

      <TextField
        label="Username"
        name="username"
        value={formData.username}
        onChange={handleChange}
        fullWidth
        margin="normal"
      />
      <TextField
        label="Current Password"
        name="password"
        type="password"
        value={formData.password}
        onChange={handleChange}
        fullWidth
        margin="normal"
        error={!!error}
        helperText={error}
      />
      <TextField
        label="New Password"
        name="newPassword"
        type="password"
        value={formData.newPassword}
        onChange={handleChange}
        fullWidth
        margin="normal"
      />
      <Button
        variant="contained"
        color="primary"
        onClick={handleUpdate}
        sx={{ mt: 2 }}
      >
        Save Changes
      </Button>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={closeSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={closeSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ProfileTab;
